package co.edu.umb.boleteria.web;
import co.edu.umb.boleteria.repository.LocalidadRepository;import co.edu.umb.boleteria.web.dto.LocalidadDto;import co.edu.umb.boleteria.web.excepciones.NoEncontradaException;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/localidades") public class LocalidadController {final LocalidadRepository repo;public LocalidadController(LocalidadRepository r){repo=r;}@GetMapping @Transactional(readOnly=true) public List<LocalidadDto> listar(){return repo.findAll().stream().map(LocalidadDto::of).toList();}@GetMapping("/{id}") @Transactional(readOnly=true) public LocalidadDto detalle(@PathVariable UUID id){return repo.findById(id).map(LocalidadDto::of).orElseThrow(NoEncontradaException::new);}}
